BEGIN;
CREATE TABLE "FaixaGraduacao" (id UUID PRIMARY KEY,nome TEXT NOT NULL UNIQUE,chave TEXT NOT NULL UNIQUE,cor TEXT NOT NULL,ordem INTEGER NOT NULL CHECK(ordem BETWEEN 0 AND 9999),situacao TEXT NOT NULL CHECK(situacao IN ('ativo','inativo')),"criadoEm" TEXT NOT NULL,"atualizadoEm" TEXT NOT NULL);
CREATE TABLE "GrauFaixa" (id UUID PRIMARY KEY,"faixaId" UUID NOT NULL REFERENCES "FaixaGraduacao"(id) ON DELETE RESTRICT,numero INTEGER NOT NULL CHECK(numero BETWEEN 0 AND 99),situacao TEXT NOT NULL CHECK(situacao IN ('ativo','inativo')),"criadoEm" TEXT NOT NULL,"atualizadoEm" TEXT NOT NULL,UNIQUE("faixaId",numero),UNIQUE("faixaId",id));
INSERT INTO "FaixaGraduacao" VALUES ('00000000-0000-4000-8100-000000000001','Branca','branca','#F3F4F6',1,'ativo','2026-10-26T00:00:00.000Z','2026-10-26T00:00:00.000Z'),
