ALTER TABLE "Aluno" ADD COLUMN "faixaId" UUID REFERENCES "FaixaGraduacao"(id) ON DELETE RESTRICT;
ALTER TABLE "Aluno" ADD COLUMN "grauId" UUID REFERENCES "GrauFaixa"(id) ON DELETE RESTRICT;
INSERT INTO "FaixaGraduacao" SELECT gen_random_uuid(),a.faixa,'legada:'||lower(trim(a.faixa)),'#64748B',100,'ativo','2026-10-26T00:00:00.000Z','2026-10-26T00:00:00.000Z' FROM (SELECT DISTINCT faixa FROM "Aluno") a WHERE NOT EXISTS(SELECT 1 FROM "FaixaGraduacao" f WHERE f.nome=a.faixa);
UPDATE "Aluno" SET "faixaId"=(SELECT id FROM "FaixaGraduacao" WHERE nome="Aluno".faixa);
ALTER TABLE "Aluno" ADD CONSTRAINT "Aluno_grau_faixa_check" CHECK("grauId" IS NULL OR "faixaId" IS NOT NULL);
ALTER TABLE "Aluno" ADD CONSTRAINT "Aluno_grau_faixa_fkey" FOREIGN KEY("faixaId","grauId") REFERENCES "GrauFaixa"("faixaId",id) ON DELETE RESTRICT;
CREATE FUNCTION validar_graduacao_aluno() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW."faixaId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM "FaixaGraduacao" WHERE id=NEW."faixaId" AND nome=NEW.faixa) THEN RAISE EXCEPTION 'Graduacao incompativel' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER "Aluno_graduacao_nome" BEFORE INSERT OR UPDATE OF faixa,"faixaId","grauId" ON "Aluno" FOR EACH ROW EXECUTE FUNCTION validar_graduacao_aluno();
COMMIT;
